contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // target and calldata; value forwarded from C is limited by C's current balance
    function run(address target, bytes calldata data) public payable {
        // observe before balance
        uint beforeBalance = address(c).balance;

        // ensure this contract is the owner (it is, because it deployed c) and that target is any address
        // perform the call and record whether it reverted
        bool reverted;
        c.sendMoney(target, 0, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;

        // General rule: sendMoney cannot increase the contract balance
        assert(afterBalance <= beforeBalance);
    }

    receive() external payable {}
}

